// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openTransferOwnershipModal, signIn } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(77000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (error: Error) => pageErrors.push(error.message));

    // Credential(s) read from the environment — never recorded into this file. Set these before running.
    if (process.env.SKYRAMP_UI_PASSWORD === undefined) {
        throw new Error("SKYRAMP_UI_PASSWORD is not set: this test replays a login and needs that credential in the environment");
    }
    const loginPassword = process.env.SKYRAMP_UI_PASSWORD ?? "";

    await page.goto(`${baseUrl}/login`);
    await signIn(page, "testbot-admin", loginPassword);
    await page.waitForURL((u) => !u.pathname.startsWith('/login'));
    await page.goto(`${baseUrl}/settings/collection-members`);
    await page.locator('main button.btn-error').waitFor({ state: 'visible', timeout: 10000 });
    await expect(page.getByRole("button", { name: "Transfer Ownership" })).toBeVisible();
    await openTransferOwnershipModal(page);
    await expect(page.getByRole("combobox")).toBeVisible();

    // With no new owner picked the modal must not be able to submit a transfer.
    const modal = page.locator("div.fixed.inset-0");
    await expect(modal.getByRole("button", { name: "Transfer Ownership" })).toBeDisabled();

    // The modal has to list the collection's members as candidate new owners; without one
    // there is no owner to transfer to and the transfer cannot be performed from the page.
    const selectableNewOwners = page.getByRole("combobox").locator("option:not([disabled])");
    await expect(selectableNewOwners).not.toHaveCount(0);

    expect(pageErrors, 'the page raised no script errors').toEqual([]);
});
